package terminal

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestPiMarkdownParityMatchesPinnedRenderer compares psi's Markdown output
// with the pinned Pi renderer.
//
// The fixtures in testdata/pi-markdown-parity.json are generated by
// scripts/pi-markdown-reference.mjs from the Pi checkout in temp/pi-mono. Pi
// renders assistant prose with a two cell margin on both sides; psi keeps the
// same left margin and reserves one cell for terminal autowrap, so the
// recorded psi width is one cell smaller than the Pi width.
func TestPiMarkdownParityMatchesPinnedRenderer(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "pi-markdown-parity.json"))
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Reference string `json:"reference"`
		Note      string `json:"note"`
		Fixtures  []struct {
			Name  string   `json:"name"`
			Text  string   `json:"text"`
			Width int      `json:"width"`
			Lines []string `json:"lines"`
		} `json:"fixtures"`
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(fixture.Reference, "d5b3de22d0e24a3e9c38a9410d3329b099717283") {
		t.Fatalf("Markdown parity fixtures must identify the pinned Pi revision: %q", fixture.Reference)
	}
	if len(fixture.Fixtures) == 0 {
		t.Fatal("Markdown parity fixtures are empty")
	}
	for _, entry := range fixture.Fixtures {
		t.Run(entry.Name, func(t *testing.T) {
			got := []string{}
			for _, row := range RenderMarkdown(entry.Text, entry.Width, true) {
				got = append(got, strings.TrimRight(row, " "))
			}
			want := []string{}
			for _, line := range entry.Lines {
				want = append(want, strings.TrimRight(line, " "))
			}
			if strings.Join(got, "\n") != strings.Join(want, "\n") {
				t.Fatalf("Markdown output differs from Pi\nwant:\n%s\ngot:\n%s", strings.Join(want, "\n"), strings.Join(got, "\n"))
			}
		})
	}
}
